        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def dedupe(xs: list) -> list:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def parse_price(s: str) -> float:
    s = s.replace('$', '').replace(',', '')
    return float(s)

def flatten(xs: list) -> list:
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def second_largest(nums: list) -> int:
    unique_nums = list(set(nums))
    if len(unique_nums) < 2:
        raise ValueError("Not enough distinct elements")
    unique_nums.sort()
    return unique_nums[-2]
